{"revision_id": "049864c4-f460-4f82-9703-21c82caba534", "source": "module TopModule (
    input c,
    input d,
    output [3:0] mux_in
);
    assign mux_in[0] = d ? 1'b1 : c;   // c | d
    assign mux_in[1] = 1'b0;
    assign mux_in[2] = c ? d : 1'b0;   // c & d
    assign mux_in[3] = d ? c : 1'b1;   // c | ~d
endmodule
"}
